<template>
 <section v-if="analysis" class="marketing-data-card" aria-label="Observed marketing performance">
  <header><h4>Observed marketing performance</h4><p>Calculated from the supplied export rows. These are recorded results, not predicted returns.</p></header>
  <p v-if="analysis.excludedTotalRows.length" class="marketing-data-note">{{ analysis.excludedTotalRows.length }} explicitly labeled total {{ analysis.excludedTotalRows.length===1?'row is':'rows are' }} excluded from charts and combined values to avoid double counting. They remain in the recorded rows below.</p>
  <p v-if="analysis.multipleCurrencies" class="marketing-data-note">Monetary values are separated by currency. There is no combined total across currencies.</p>
  <div class="marketing-data-controls"><label v-if="analysis.groups.length>1">Currency<select v-model="groupKey"><option v-for="item in analysis.groups" :key="item.key" :value="item.key">{{ item.label }}</option></select></label><label>View results<select v-model="record"><option v-if="group.aggregate && group.rows.length>1" value="summary">Combined recorded rows</option><option v-for="row in group.rows" :key="row.index" :value="String(row.index)">{{ row.label }}{{ row.date?` · ${row.date}`:'' }}</option></select></label></div>
  <p class="marketing-data-source">{{ record==='summary' ? `${group.rows.length} distinct export rows · ${group.label}` : `${selectedRow?.label || ''}${selectedRow?.date?` · ${selectedRow.date}`:''}` }}</p>
  <div class="marketing-data-metrics"><article v-for="key in visibleMetrics" :key="key"><span>{{ marketingMetrics[key] }}</span><strong>{{ format(key,shown[key],selectedRow) }}</strong></article></div>
  <p v-if="group.aggregationNote" class="marketing-data-note">{{ group.aggregationNote }} Metrics above show the selected row.</p>
  <p v-if="!group.currency" class="marketing-data-note">Currency is missing or inconsistent. Currency-dependent ratios are shown only where the underlying spend and revenue units are known.</p>
  <p v-if="insight" class="marketing-data-insight">{{ insight }}</p>
  <label v-if="chartMetrics.length" class="marketing-data-chart-select">Chart metric<select v-model="metric"><option v-for="key in chartMetrics" :key="key" :value="key">{{ marketingMetrics[key] }}</option></select></label>
  <EChart v-if="metric" :option="chart" :height="dateChart ? 285 : Math.min(520,90+chartRows.length*27)" :label="`${marketingMetrics[metric]} from supplied export rows`" :theme="theme" />
  <WorkspacePager v-model:page="chartPage" :size="20" :total="group.rows.length" label="chart rows" />
  <details class="marketing-data-records"><summary>All recorded rows ({{ analysis.allRows.length }})</summary><div class="marketing-data-table" role="region" aria-label="Recorded marketing metric rows" tabindex="0"><table><thead><tr><th>Record</th><th>Date</th><th v-for="key in allMetrics" :key="key">{{ marketingMetrics[key] }}</th></tr></thead><tbody><tr v-for="row in rawRows" :key="row.index"><th>{{ row.label }}{{ row.total?' (export total)':'' }}</th><td>{{ row.date || 'Not supplied' }}</td><td v-for="key in allMetrics" :key="key">{{ format(key,row.metrics[key],row) }}</td></tr></tbody></table></div><WorkspacePager v-model:page="rawPage" :size="20" :total="analysis.allRows.length" label="export rows" /></details>
  <details class="marketing-data-definitions"><summary>How the metrics are calculated</summary><p>CTR = clicks ÷ impressions × 100. CPC = spend ÷ clicks. CPM = spend ÷ impressions × 1,000. CPA = spend ÷ recorded conversions. ROAS = revenue ÷ spend. Missing or zero denominators produce no ratio. Monetary ratios require identified units; ROAS requires matching spend and revenue currencies.</p><p>Rows without a consistent, unique advertising identifier are not added together. Explicit export total rows stay available for inspection.</p></details>
 </section>
</template>
<script setup>
import { computed, ref, watch } from 'vue'
import EChart from './EChart.vue'
import WorkspacePager from './WorkspacePager.vue'
import { palette } from '../../workspace/charts'
import { analyzeMarketingData, marketingMetrics } from '../../workspace/marketingData'
const props=defineProps({data:{default:null},theme:{type:String,default:'light'}})
const analysis=computed(()=>analyzeMarketingData(props.data)),groupKey=ref(''),record=ref(''),metric=ref(''),chartPage=ref(0),rawPage=ref(0)
const group=computed(()=>analysis.value?.groups.find(item=>item.key===groupKey.value)||analysis.value?.groups[0])
const selectedRow=computed(()=>group.value?.rows.find(row=>String(row.index)===record.value))
const shown=computed(()=>record.value==='summary'?group.value?.aggregate || {}:selectedRow.value?.metrics || {})
const allMetrics=Object.keys(marketingMetrics)
const visibleMetrics=computed(()=>allMetrics.filter(key=>group.value?.rows.some(row=>Number.isFinite(row.metrics[key]))))
const chartMetrics=computed(()=>visibleMetrics.value.filter(key=>!['spend','revenue','cpc','cpm','cpa'].includes(key)||Boolean(group.value?.currency&&group.value.rows.every(row=>(key==='revenue'?row.revenueCurrency:row.spendCurrency)===group.value.currency))))
watch(analysis,value=>{groupKey.value=value?.groups[0]?.key||'';rawPage.value=0},{immediate:true})
watch(group,value=>{record.value=value?.aggregate&&value.rows.length>1?'summary':String(value?.rows[0]?.index??'');chartPage.value=0;metric.value=['roas','clicks','spend','impressions'].find(key=>chartMetrics.value.includes(key))||chartMetrics.value[0]||''},{immediate:true})
const number=value=>value!==0&&Math.abs(value)<0.000001?value.toExponential(2):new Intl.NumberFormat(undefined,{maximumFractionDigits:Math.abs(value)<0.01?6:2}).format(value)
function format(key,value,row){if(!Number.isFinite(value))return '—';if(key==='ctr')return number(value)+'%';if(key==='roas')return number(value)+'×';if(['spend','cpc','cpm','cpa','revenue'].includes(key)){const currency=row?(key==='revenue'?row.revenueCurrency:row.spendCurrency):group.value?.currency;return `${currency || 'Currency unknown'} ${number(value)}`}return number(value)}
const comparable=computed(()=>group.value?.rows.filter(row=>row.spendCurrency&&row.spendCurrency===row.revenueCurrency&&Number.isFinite(row.metrics.roas))||[])
const insight=computed(()=>{if(comparable.value.length<2||!group.value?.currency)return '';const best=Math.max(...comparable.value.map(row=>row.metrics.roas)),winners=comparable.value.filter(row=>row.metrics.roas===best);return winners.length===1?`${winners[0].label} recorded the highest observed ROAS: ${number(best)}× among ${comparable.value.length} comparable rows.`:`Highest observed ROAS: ${number(best)}×. ${winners.length} rows share this value.`})
const chartRows=computed(()=>group.value?.rows.slice(chartPage.value*20,(chartPage.value+1)*20)||[])
const dateChart=computed(()=>chartRows.value.length>1&&chartRows.value.every(row=>row.date)&&new Set(chartRows.value.map(row=>row.date+'@'+(row.labelField?row.label:''))).size===chartRows.value.length)
const chart=computed(()=>{
 props.theme;const colors=palette(),rows=chartRows.value,key=metric.value
 const base={tooltip:{trigger:'axis',renderMode:'richText',confine:true,valueFormatter:value=>format(key,value)},grid:{left:10,right:30,top:dateChart.value?45:18,bottom:30,containLabel:true},textStyle:{fontFamily:'inherit',color:colors.text}}
 if(dateChart.value){const dates=[...new Set(rows.map(row=>row.date))].sort(),labels=[...new Set(rows.map(row=>row.labelField?row.label:marketingMetrics[key]))];return {...base,legend:{type:'scroll',textStyle:{color:colors.muted}},xAxis:{type:'category',data:dates,axisLabel:{color:colors.muted}},yAxis:{type:'value',axisLabel:{color:colors.muted},splitLine:{lineStyle:{color:colors.line}}},series:labels.map((label,index)=>({name:label,type:'line',connectNulls:false,symbolSize:7,itemStyle:{color:colors.series[index%colors.series.length]},data:dates.map(date=>rows.find(row=>row.date===date&&(row.labelField?row.label:marketingMetrics[key])===label)?.metrics[key]??null)}))}}
 return {...base,xAxis:{type:'value',axisLabel:{color:colors.muted},splitLine:{lineStyle:{color:colors.line}}},yAxis:{type:'category',data:rows.map(row=>row.label+(row.date?` · ${row.date}`:'')).reverse(),axisLabel:{color:colors.text,width:155,overflow:'truncate'}},series:[{name:marketingMetrics[key],type:'bar',data:rows.map(row=>row.metrics[key]).reverse(),barMaxWidth:19,itemStyle:{color:colors.accent,borderRadius:[0,4,4,0]}}]}
})
</script>
<style scoped>
.marketing-data-card{margin:15px 0;padding:20px;border:1px solid var(--line);border-radius:15px;background:var(--panel);min-width:0}.marketing-data-card h4{font-size:15px;font-weight:550;margin:0 0 7px}.marketing-data-card header>p,.marketing-data-note{font-size:11px;line-height:1.8;color:var(--muted)}.marketing-data-note{margin:12px 0}.marketing-data-controls{display:flex;flex-wrap:wrap;gap:10px;margin:17px 0 10px}.marketing-data-controls label,.marketing-data-chart-select{display:flex;align-items:center;gap:8px;font-size:11px;color:var(--muted)}.marketing-data-card select{max-width:300px;padding:7px 9px;border:1px solid var(--line);border-radius:8px;background:var(--panel-2);color:var(--text);font:inherit;font-size:11px}.marketing-data-source{font-size:10px;color:var(--muted);line-height:1.7;margin:8px 0 12px}.marketing-data-metrics{display:grid;grid-template-columns:repeat(auto-fit,minmax(125px,1fr));gap:9px}.marketing-data-metrics article{padding:13px;border:1px solid var(--line);border-radius:11px;background:var(--panel-2);min-width:0}.marketing-data-metrics span{display:block;font-size:10px;line-height:1.6;color:var(--muted);margin-bottom:7px}.marketing-data-metrics strong{display:block;font-size:17px;font-weight:550;font-variant-numeric:tabular-nums;overflow-wrap:anywhere}.marketing-data-insight{font-size:12px;line-height:1.8;margin:15px 0;color:var(--text)}.marketing-data-chart-select{margin-top:20px}.marketing-data-records,.marketing-data-definitions{margin-top:16px;padding-top:14px;border-top:1px solid var(--line);font-size:11px;color:var(--muted)}.marketing-data-card summary{cursor:pointer}.marketing-data-definitions p{margin-top:10px;line-height:1.8}.marketing-data-table{max-width:100%;overflow:auto;margin-top:12px}.marketing-data-table table{border-collapse:collapse;width:100%;font-size:11px;text-align:left}.marketing-data-table th,.marketing-data-table td{padding:10px;border-bottom:1px solid var(--line);white-space:nowrap}.marketing-data-table th{font-weight:550}.marketing-data-table thead{background:var(--panel-2)}@media(max-width:600px){.marketing-data-card{padding:15px}.marketing-data-controls{display:grid}.marketing-data-card select{max-width:230px}.marketing-data-metrics{grid-template-columns:repeat(2,minmax(0,1fr))}.marketing-data-metrics strong{font-size:15px}}
</style>
